function AI:observe(foe)
    local s = self.seen
    s[#s + 1] = {state = foe.state, t = foe.t, x = foe.x, y = foe.y, vy = foe.vy, move = foe.move, moveId = foe.moveId,
                 airMove = foe.airMove}
