                if p.energy >= 100 and self:rand() < lv.burstUse then out = B.BU
                elseif p.skillCd == 0 then out = B.SK end
            elseif id == 'airLight' then out = B.HP end
            if self.lastOut == out then out = 0 end
            self.lastOut = out
