local G = {}

G.RECT, G.ELLIPSE, G.TRI, G.STAR4, G.STAR5, G.RING = 100001, 100002, 100003, 100004, 100005, 100006

local env, safe, realSafe, Color
local N = {calls = 0, pos = 0, size = 0, col = 0, vis = 0, par = 0, txt = 0, tw = 0}
