function G.defer(on) safe = on and deferred or realSafe; direct = not on end
function G.flush(n)
    local stop = math.min(qt, qh + n - 1)
    for i = qh, stop do
        local t = queue[i]
        queue[i] = nil
        realSafe(table.unpack(t, 1, t.n))
    end
    qh = stop + 1
    return qt - qh + 1
end
