    end
    return self
end

function Node:pos(x, y)
    x, y = q(x), q(y)
    if x ~= self.x or y ~= self.y then
        self.x, self.y = x, y
        N.pos = N.pos + 1
        if direct then self.c:SetAnchoredPosition(x, y) else safe(self.c.SetAnchoredPosition, self.c, x, y) end
    end
    return self
