function Node:size(w, h)
    if w < 0 then w = 0 end
    if h < 0 then h = 0 end
    w, h = q(w), q(h)
    if w ~= self.w or h ~= self.h then
        self.w, self.h = w, h
        N.size = N.size + 1
        if direct then self.c:SetSizeDelta(w, h) else safe(self.c.SetSizeDelta, self.c, w, h) end
