        {id = 'back', label = '返回'},
    }
    self.sub = 'versus'
    self.menu = UI.menu(app, app.layers.ui, self.items, menuOpts(self, 1,
        function(id)
            if id == 'back' then self:mainMenu(2)
            elseif id == 'vcpu' then app:travel('select', {mode = 'versus', cpu = true})
            elseif id == 'online' then app:travel('online')
            end
        end,
