        L:rect(x, y - CARD_H / 2 + 29, CARD_W, 3, ec, 1)
        L:label(c.name, x, y - CARD_H / 2 + 14, CARD_W, 28, 15, hot and UI.TEXT or UI.WHITE, 'c', nil, 1)
