        -- sakura branches in front
        for i = 1, 10 do
            add(near, ELLIPSE, -1700 + hsh(i * 13) * 400, 900 + hsh(i * 2) * 200, 280, 170, {255, 170, 210}, 0, 0.3)
            add(near, ELLIPSE, 1700 - hsh(i * 17) * 400, 950 + hsh(i * 4) * 200, 280, 170, {250, 150, 200}, 0, 0.3)
        end
