    L:shape(G.ELLIPSE, 0, py, 54, 54, SLATE, 0.55)
    L:shape(G.RING, 0, py, 54, 54, WHITE, 0.5)
    L:rect(-7, py, 6, 20, WHITE, 0.85)
    L:rect(7, py, 6, 20, WHITE, 0.85)
    L:finish()
